/**
 * The one request the page around a frame may make of it: show the
 * client's own settings menu, which a framed page has no button for (its
 * round button is hidden there; the page around it has a Settings row in
 * its own menu instead).
 *
 * The request is fixed and carries nothing: exactly `{ type:
 * 'webverse-show-menu' }`, no other field. It is taken only from the window
 * directly around this one. A page the world embeds is a window inside this
 * one, never the one around it, so it cannot make it; the world's own
 * scripts do not run in this window. Any page may embed a frame page and
 * send it, and all it can do is open the visitor's own menu on the
 * visitor's own screen, which the visitor can close. Anything else is not
 * read, and is not an error.
 *
 * Loaded after the page has started, and only in a framed page.
 */

export const SHOW_MENU = { type: 'webverse-show-menu' } as const;

/** True only for an object whose one own field is `type: 'webverse-show-menu'`. Never throws. */
export function isShowMenu(data: unknown): boolean {
  try {
    if (typeof data !== 'object' || data === null || Array.isArray(data)) return false;
    if (Object.getPrototypeOf(data) !== Object.prototype) return false;
    const keys = Object.keys(data);
    return keys.length === 1 && keys[0] === 'type' && (data as { type?: unknown }).type === SHOW_MENU.type;
  } catch {
    return false;
  }
}

/** The slice of the client's settings menu this needs. */
export interface ShownMenu {
  open(): void;
  isOpen(): boolean;
}

/**
 * Opens `menu` each time the window around `win` asks, unless it is open
 * already or the world has taken the menu away (its button is not on the
 * page), and puts the keyboard in it.
 */
export function listenForShowMenu(
  win: { parent: unknown; addEventListener(type: 'message', listener: (event: { source: unknown; data: unknown }) => void): void },
  doc: Document,
  menu: ShownMenu,
): void {
  if (win.parent === win) return;
  win.addEventListener('message', (event) => {
    if (event.source !== win.parent || !isShowMenu(event.data)) return;
    if (menu.isOpen() || doc.querySelector('[data-webverse-menu-button]') === null) return;
    menu.open();
    const panel = doc.querySelector<HTMLElement>('[data-webverse-menu]');
    if (panel === null) return;
    if (!panel.hasAttribute('tabindex')) panel.setAttribute('tabindex', '-1');
    panel.focus();
  });
}
